 const submitAuth=async e=>{
  e.preventDefault();
  if(authPending||authRequestLock.current)return;
  setAuthError('');setAuthMessage('');
  if(!supabase){setAuthError('Authentication is not configured yet. Add the Supabase project URL and anon key to .env.local.');return}
  authRequestLock.current=true;setAuthPending(true);
  try{
   if(authMethod==='email'){
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(authInput))throw Error('Enter a valid email address.');
    if(authMode==='recover'){const {error}=await supabase.auth.resetPasswordForEmail(authInput,{redirectTo:window.location.origin});if(error)throw error;setAuthMessage('Password reset link sent. Check your email.')}
    else if(authMode==='reset'){const {error}=await supabase.auth.updateUser({password:authPassword});if(error)throw error;setAuthMessage('Your password was updated.');setShowAuth(false)}
    else if(authMode==='register'){if(authPassword.length<8)throw Error('Use a password with at least 8 characters.');const {data,error}=await supabase.auth.signUp({email:authInput,password:authPassword,options:{emailRedirectTo:window.location.origin}});if(error)throw error;if(data.session){setShowAuth(false);setAuthMessage('')}else setAuthMessage('Check your email to verify your account and finish signing in.')}
    else{const {error}=await supabase.auth.signInWithPassword({email:authInput,password:authPassword});if(error)throw error;setShowAuth(false)}
   }else if(!otpSent){
    const phone=normalizePhoneNumber(authInput,authCountry);
    await requestPhoneOtp(supabase,phone,authMode);
    setPendingPhone(phone);setAuthOtp('');setOtpSent(true);setOtpCooldown(60);setAuthMessage(`Verification request accepted for ${phone}. Enter the code if the SMS arrives.`);
   }else{
    if(!pendingPhone)throw Error('Enter your phone number again to request a new code.');
    const data=await verifyPhoneOtp(supabase,pendingPhone,authOtp);
    const signedInUser=data.user||data.session?.user;
    if(signedInUser)setUser(signedInUser);
    setShowAuth(false);setOtpSent(false);setOtpCooldown(0);setPendingPhone('');setAuthOtp('');setAuthInput('');
    setNotice('Phone number verified. You are signed in.');
   }
  }catch(err){setAuthError(authMethod==='phone'?phoneAuthErrorMessage(err):(err.message||'Authentication failed. Please try again.'))}
  finally{authRequestLock.current=false;setAuthPending(false)}
 };
